framework_component_specs.ArticleCalendarSection:
# ArticleCalendarSection

Interactive article archive calendar with month navigation, date filtering, and linked pagination. Use on archive pages, not within individual articles.

**File:** `app/articles/ArticleCalendarSection.tsx`

## Props

| Required prop | Type | Description |
|---|---|---|
| `title` | `string` | Section title |
| `articles` | `Article[]` | All calendar articles |
| `paginatedArticles` | `Article[]` | Visible articles |
| `currentPage` | `number` | Current page |
| `totalPages` | `number` | Total pages |
| `pageSize` | `number` | Articles per page |
| `paginationBasePath` | `string` | Pagination base URL |

| Optional prop | Type | Default / description |
|---|---|---|
| `id` | `string` | `"calendar"`; section anchor |
| `paginationHash` | `string` | Unset; pagination fragment |
| `selectedDate` | `Date` | Unset; selected day |
| `onDateSelect` | `(date: Date) => void` | Unset; selection callback |

## Working React Router example

The parent supplies page data; React Router links change the `page` query parameter. Date selection filters the full collection independently of pagination.

```tsx
import { useState } from "react";
import { Link } from "react-router";

type Article = {
  slug: string;
  title: string;
  date: string; // ISO date string
  description?: string;
  image?: string;
};

type Props = {
  title: string;
  articles: Article[];
  paginatedArticles: Article[];
  currentPage: number;
  totalPages: number;
  pageSize: number;
  paginationBasePath: string;
  id?: string;
  paginationHash?: string;
  selectedDate?: Date;
  onDateSelect?: (date: Date) => void;
};

function dateKey(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

export function ArticleCalendarSection(props: Props) {
  const [month, setMonth] = useState(new Date());
  const [picked, setPicked] = useState<Date>();
  const selected = props.selectedDate ?? picked;
  const key = selected ? dateKey(selected) : null;
  const visible = key
    ? props.articles.filter((article) => article.date.slice(0, 10) === key)
    : props.paginatedArticles;
  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  const count = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate();
  const pageUrl = (page: number): string => {
    const url = new URL(props.paginationBasePath, "https://example.invalid");
    url.searchParams.set("page", String(page));
    url.hash = props.paginationHash ?? "";
    return `${url.pathname}${url.search}${url.hash}`;
  };

  return (
    <section id={props.id ?? "calendar"}>
      <h2>{props.title}</h2>
      {[-1, 1].map((step) => (
        <button key={step} type="button" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + step, 1))}>
          {step < 0 ? "Previous month" : "Next month"}
        </button>
      ))}
      <p aria-live="polite">{month.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</p>
      <div className="grid grid-cols-7">
        {"Sun Mon Tue Wed Thu Fri Sat".split(" ").map((day) => <span key={day}>{day}</span>)}
        {Array.from({ length: first.getDay() }, (_, i) => <span key={`blank-${i}`} />)}
        {Array.from({ length: count }, (_, i) => {
          const date = new Date(month.getFullYear(), month.getMonth(), i + 1);
          const day = dateKey(date);
          return (
            <button key={day} type="button" aria-pressed={key === day} onClick={() => { setPicked(date); props.onDateSelect?.(date); }}>
              {i + 1}{props.articles.some((article) => article.date.startsWith(day)) ? " •" : ""}
            </button>
          );
        })}
      </div>
      {visible.map((article) => <article key={article.slug}><Link to={`/articles/${article.slug}`}>{article.title}</Link></article>)}
      {!key && <nav aria-label="Article pagination">
        {props.currentPage > 1 && <Link to={pageUrl(props.currentPage - 1)}>Previous</Link>}
        <span>{props.currentPage} / {props.totalPages}</span>
        {props.currentPage < props.totalPages && <Link to={pageUrl(props.currentPage + 1)}>Next</Link>}
      </nav>}
    </section>
  );
}
```

## Presentation and accessibility

Use highlighted article dots, prominent selection, subtle today styling, and a responsive list. Native buttons support keyboard activation. For a full ARIA grid, add rows/gridcells, `aria-selected`, roving focus, and arrow-key navigation together.

**Semantic hints:** `calendar`, `schedule`, `dates`, `events-calendar`, `date-picker`, `archive`, `timeline`

