# ArticleCompanyHighlightCTA

Prominent product/feature CTA with text, navigation actions, and an image. Use when more visual impact than ArticleCompanyCTA is needed.

## Props

| Prop | Type | Required / Default | Description |
|---|---|---|---|
| `title` | `string` | Required | CTA heading |
| `body` | `string` | Required | Description |
| `primaryButton` | `ButtonProps` | Required | Primary action |
| `image` | `string` | Required | Product/feature image URL |
| `label` | `string` | Optional | Small label above title |
| `secondaryButton` | `ButtonProps` | Optional | Secondary action |
| `note` | `string` | Optional | Small note text |
| `id` | `string` | Optional | Section anchor ID |
| `className` | `string` | Optional | Additional classes |
| `imageAlt` | `string` | `title` | Meaningful image alt text |
| `imagePosition` | `"left" \| "right"` | `"right"` | Image placement |

`ButtonProps`: `text: string`, `href: string`, `variant?: "primary" | "secondary" | "outline"`. Omitted variants default by action role.

## Semantic Hints

`cta`, `highlight-cta`, `featured-cta`, `accent-cta`, `product-cta`, `demo-cta`, `showcase-cta`

## React Router Implementation

Place in `app/articles/ArticleCompanyHighlightCTA.tsx`. Internal actions use `Link`; external URLs use anchors. No client directive or loader is needed.

```tsx
import { Link } from "react-router";

type ButtonProps = {
  text: string;
  href: string;
  variant?: "primary" | "secondary" | "outline";
};

type Props = {
  title: string;
  body: string;
  primaryButton: ButtonProps;
  image: string;
  label?: string;
  secondaryButton?: ButtonProps;
  note?: string;
  id?: string;
  className?: string;
  imageAlt?: string;
  imagePosition?: "left" | "right";
};

function renderAction(button: ButtonProps, primary: boolean): React.JSX.Element {
  const variant = button.variant ?? (primary ? "primary" : "secondary");
  const className = `rounded px-4 py-3 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${
    variant === "primary"
      ? "bg-blue-700 text-white font-bold"
      : variant === "outline"
        ? "border border-gray-600 text-gray-900"
        : "bg-gray-100 text-gray-900"
  }`;
  return /^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(button.href)
    ? <a href={button.href} className={className}>{button.text}</a>
    : <Link to={button.href} className={className}>{button.text}</Link>;
}

export function ArticleCompanyHighlightCTA(props: Props): React.JSX.Element {
  return (
    <section id={props.id} aria-label={props.title}
      className={`rounded-xl border bg-white p-6 ${props.className ?? ""}`}>
      <div className="grid items-center gap-6 md:grid-cols-2">
        <div>
          {props.label && <span className="text-sm uppercase text-blue-700">{props.label}</span>}
          <h2 className="text-3xl font-bold">{props.title}</h2>
          <p className="my-4">{props.body}</p>
          <div className="flex flex-wrap gap-3">
            {renderAction(props.primaryButton, true)}
            {props.secondaryButton && renderAction(props.secondaryButton, false)}
          </div>
          {props.note && <p className="mt-3 text-sm">{props.note}</p>}
        </div>
        <div className={props.imagePosition === "left" ? "order-first" : "order-last"}>
          <img src={props.image} alt={props.imageAlt ?? props.title}
            className="h-auto w-full rounded-lg object-contain" />
        </div>
      </div>
    </section>
  );
}

export default function Example(): React.JSX.Element {
  return (
    <ArticleCompanyHighlightCTA
      title="AI-Powered Analytics"
      body="Discover real-time insights."
      primaryButton={{ text: "Start Free Trial", href: "/trial" }}
      image="/images/analytics-dashboard.png"
    />
  );
}
```

